import datetime

class Time:
    def __init__(self, hour, minute, second, microsecond):
        self.hour = hour
        self.minute = minute
        self.second = second
        self.microsecond = microsecond

class LocalTime(Time):
    def __init__(self, hour, minute, second, microsecond, tz=None):
        super().__init__(hour, minute, second, microsecond)
        self.tz = tz

def hydrate_time(nanoseconds, tz=None):
    """ Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds:
    :param tz:
    :return: Time
    """
    seconds, nanos = divmod(nanoseconds, 1_000_000_000)
    minutes, seconds = divmod(seconds, 60)
    hours, minutes = divmod(minutes, 60)
    microseconds = nanos // 1000

    if tz:
        return LocalTime(hour, minute, second, microseconds, tz)
    else:
        return Time(hour, minute, second, microseconds)
