def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    class MetaPoint(abc.ABCMeta):
        """Meta class for Point to enforce SRID mapping."""
        def __call__(cls, *args, srid=None, **kwargs):
            # Enforce SRID mapping
            if srid is not None and srid not in srid_map:
                raise ValueError(f"Invalid SRID: {srid}. Valid SRIDs are {srid_map.keys()}")
            return super().__call__(*args, **kwargs)

    class Point(ABC, metaclass=MetaPoint):
        """Base class for Point with SRID validation."""
        _fields = fields

        def __new__(cls, *args, **kwargs):
            # Convert positional arguments to keyword arguments based on field names
            if len(args) != len(cls._fields):
                raise ValueError(f"Expected {len(cls._fields)} arguments, got {len(args)}")
            kwargs.update(dict(zip(cls._fields, args)))
            return super().__new__(cls, **kwargs)

        def __init__(self, *args, srid=None, **kwargs):
            self.srid = srid
            for key, value in kwargs.items():
                setattr(self, key, value)

        def __repr__(self):
            args = ', '.join(f"{key}={getattr(self, key)!r}" for key in self._fields)
            if self.srid is not None:
                return f"{self.__class__.__name__}({args}, srid={self.srid!r})"
            return f"{self.__class__.__name__}({args})"

    return Point
