def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    class Point:
        __slots__ = fields + ['srid']

        def __init__(self, *args, srid=0, **kwargs):
            if len(args) + len(kwargs) != len(fields) + 1:
                raise TypeError(f"{name} takes {len(fields) + 1} arguments but {len(args) + len(kwargs)} were given")
            for field, value in zip(fields, args):
                setattr(self, field, value)
            self.srid = srid

        def __repr__(self):
            field_values = ", ".join(f"{field}={getattr(self, field)!r}" for field in fields)
            return f"{name}({field_values}, srid={self.srid!r})"

    Point.__name__ = name
    Point.srid_map = srid_map
    return Point

