def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    import os, subprocess
    if os.name == 'nt':
        new_cmd = list(cmd)
        if new_cmd[0].startswith('#!'):
            script_path = new_cmd[0][2:].strip()
            if not os.path.isabs(script_path):
                script_path = os.path.join(os.path.dirname(cmd[1]), script_path)
            new_cmd[0] = script_path
            if subprocess.call(['where', script_path], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL) != 0:
                new_cmd[0] = os.path.realpath(script_path)
        return tuple(new_cmd)
    else:
        return cmd

