def ttl_cache(maxsize=128, ttl=600, timer=time.monotonic, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm with a per-item time-to-live (TTL) value.
    """
    class TTLCache:
        def __init__(self, maxsize, ttl, timer, typed):
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed
            self.cache = {}
            self.expiration_times = {}

        def __getitem__(self, key):
            if key not in self.cache:
                raise KeyError(key)
            if self.timer() - self.expiration_times[key] > self.ttl:
                del self.cache[key]
                del self.expiration_times[key]
                raise KeyError(key)
            return self.cache[key]

        def __setitem__(self, key, value):
            if self.typed:
                key = (type(key), key)
            self.cache[key] = value
            self.expiration_times[key] = self.timer()
            if len(self.cache) > self.maxsize:
                oldest_key = min(self.expiration_times, key=self.expiration_times.get)
                del self.cache[oldest_key]
                del self.expiration_times[oldest_key]

        def __len__(self):
            return len(self.cache)

    def decorator(func):
        cache = TTLCache(maxsize, ttl, timer, typed)

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                return cache[(args, tuple(sorted(kwargs.items())))]
            except KeyError:
                result = func(*args, **kwargs)
                cache[(args, tuple(sorted(kwargs.items())))] = result
                return result

        return wrapper

    return decorator
