            self.cache = OrderedDict()
            self.maxsize = maxsize
            self.ttl = ttl
            self.timer = timer
            self.typed = typed

        def __getitem__(self, key):
            value, expire = self.cache[key]
            if expire < self.timer():
                del self.cache[key]
                raise KeyError(key)
            return value

        def __setitem__(self, key, value):
            expire = self.timer() + self.ttl
            if key in self.cache:
                del self.cache[key]
            self.cache[key] = (value, expire)
            if len(self.cache) > self.maxsize:
                self.cache.popitem(last=False)

        def __contains__(self, key):
            try:
                self.__getitem__(key)
                return True
            except KeyError:
                return False

        def __len__(self):
            return len(self.cache)

    def decorator(func):
        cache = TTLCache(maxsize, ttl, timer, typed)

        def wrapper(*args, **kwargs):
            nonlocal cache
            key = args if not typed else (args, tuple(kwargs.items()))
            try:
                return cache[key]
            except KeyError:
                value = func(*args, **kwargs)
                cache[key] = value
                return value
        return wrapper
    return decorator
