    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.

    """

    def decorator(func):
        from collections import OrderedDict
        import sys

        class Node:
            def __init__(self, key, value, count=1):
                self.key = key
                self.value = value
                self.count = count

        class LFUCache:
            def __init__(self, capacity):
                self.capacity = capacity
                self.cache = OrderedDict()
                self.counts = {}
                self.min_count = 0

            def get(self, key):
                if key not in self.cache:
                    return -1
                node = self.cache[key]
                del self.cache[key]
                self.cache[key] = self.incr_count(node)
                return node.value

            def put(self, key, value):
                if key in self.cache:
                    self.cache[key] = self.incr_count(self.cache[key], value)
                else:
                    if len(self.cache) >= self.capacity:
                        k, v = self.cache.popitem(last=False)
                        del self.counts[v.count]
                    node = Node(key, value)
                    self.cache[key] = node
                    self.counts[1] = self.cache
                    self.min_count = 1

            def incr_count(self, node, value=None):
                node.count += 1
                if node.count not in self.counts:
                    self.counts[node.count] = OrderedDict()
                if node.key in self.counts[node.count - 1]:
                    del self.counts[node.count - 1][node.key]
                if not self.counts[node.count - 1]:
                    if node.count - 1 == self.min_count:
                        self.min_count += 1
                    del self.counts[node.count - 1]
                if value is not None:
                    node.value = value
                self.counts[node.count][node.key] = node
                return node

        cache = LFUCache(maxsize)
        if typed:
            cache_key = lambda *args, **kwargs: (func.__qualname__, args, tuple(sorted(kwargs.items())) if kwargs else ())
        else:
            cache_key = lambda *args, **kwargs: (func.__qualname__, args, tuple(sorted(kwargs.items())) if kwargs else ())

        def wrapper(*args, **kwargs):
            k = cache_key(*args, **kwargs)
            try:
                return cache.get(k)
            except KeyError:
                pass  # key not found
            v = func(*args, **kwargs)
            cache.put(k, v)
            return v

        return _update_wrapper(wrapper, func)

    return decorator

