    class LFUCache:
        def __init__(self, maxsize, typed):
            self.maxsize = maxsize
            self.typed = typed
            self.cache = OrderedDict()
            self.freq = Counter()

        def __call__(self, func):
            def wrapper(*args, **kwargs):
                key = (args, tuple(sorted(kwargs.items()))) if self.typed else (args, tuple(kwargs.items()))
                if key in self.cache:
                    self.freq[key] += 1
                elif len(self.cache) >= self.maxsize:
                    least_freq = min(self.freq.values())
                    for k, v in list(self.cache.items()):
                        if self.freq[k] == least_freq:
                            self.cache.pop(k)
                            self.freq.pop(k)
                            break
                    key = (args, tuple(sorted(kwargs.items()))) if self.typed else (args, tuple(kwargs.items()))
                v = func(*args, **kwargs)
                self.cache[key] = v
                self.freq[key] = 1
                return v
            return wrapper

    return LFUCache(maxsize, typed)
