def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def find_deadends(cls):
        return all(not issubclass(b, cls) for b in classes if b != cls)

    def ancestor_next(bases, base, acc):
        anew = filter(lambda x: issubclass(x, base) and not issubclass(base, x) and find_deadends(x), bases)
        return list(acc) + list(anew)

    acc = []
    bases = []
    for a in classes:
        bases = ancestor_next(bases, a, acc)

    return bases

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    minimal = []
    for cls in classes:
        for m in minimal:
            if issubclass(cls, m):
                break
        else:
            for i, m in enumerate(minimal):
                if issubclass(m, cls):
                    minimal[i] = cls
                    break
            else:
                minimal.append(cls)
    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""

    def is_minimal(bases, candidate):
        return all(b not in candidate for b in bases if b is not candidate)

    seen = set()
    minimal = []

    for cls in classes:
        if is_minimal(minimal, cls):
            minimal.append(cls)
        for base in cls.__bases__:
            seen.add(base)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if id(cls) in seen:
            continue
        seen.add(id(cls))
        indirectly_inherited = all(id(bas) in seen for bas in cls.__bases__)
        if not indirectly_inherited:
            result.append(cls)
            for bas in cls.__bases__:
                minimalBases(bas.__bases__)
    return result

