    for field in self.fields:
        value = getattr(self, field)
        if field.startswith('error'):
            error_type = field[len('error_'):2] or field[len('error_'):]
            if error_type in ['x', 'y', 'z']:
                if 'error' not in context:
                    context['error'] = {}
                if error_type not in context['error']:
                    context['error'][error_type] = {}
                context['error'][error_type]['index'] = self.fields.index(field)
        else:
            if 'value' not in context:
                context['value'] = {}
            context['value'][field] = value
