    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    if 'error' in context:
        if 'E' in self.fields:
            index = self.fields.index('E')
            context['error']['x'] = {'index': index}
        if 't' in self.fields:
            index = self.fields.index('t')
            context['error']['y'] = {'index': index}
        if 'error_E_low' in self.fields:
            index = self.fields.index('error_E_low')
            context['error']['z'] = {'index': index}

def _update_context(self, context):
    """Update *context* with the properties of this graph.

    *context.error* is appended with indices of errors.
    Example subcontext for a graph with fields "E,t,error_E_low":
    {"error": {"x_low": {"index": 2}}}.
    Note that error names are called "x", "y" and "z"
    (this corresponds to first three coordinates,
    if they are present), which allows to simplify plotting.
    Existing values are not removed
    from *context.value* and its subcontexts.

    Called on "destruction" of the graph (for example,
    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """

    if not hasattr(context, 'error'):
        context.error = {}

    if not hasattr(context, 'value'):
        context.value = {}

    error_fields = ['error_' + field for field in ['E', 't', 'x', 'y', 'z'] if hasattr(self, field)]
    for field in error_fields:
        error_index = getattr(self, field)
        if error_index is not None and error_index not in context.error:
            context.error[field] = {'index': error_index}

    value_fields = [field for field in ['E', 't', 'x', 'y', 'z'] if hasattr(self, field)]
    for field in value_fields:
        value = getattr(self, field)
        if value is not None:
            if field not in context.value:
                context.value[field] = {}
            context.value[field]['value'] = value

