import re
from typing import Dict, List, Union

class ValidationError(Exception):
    def __init__(self, messages: List[Dict[str, str]]):
        self.messages = messages
        super().__init__(self.messages)

def _validate_labels(labels: Dict[str, Union[str, List[str]]]):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    label_key_regex = r'^[a-zA-Z0-9_]+$'
    label_value_regex = re.compile(r'^[a-zA-Z0-9_.-]+$')

    errors = []

    for key, value in labels.items():
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): 'expected string or bytes-like object'})
        elif not re.match(label_key_regex, key):
            errors.append({key: f"Label key '{key}' does not match the regex {label_key_regex}"})
        if isinstance(value, list):
            for v in value:
                if not isinstance(v, (str, bytes)):
                    errors.append({str(v): 'expected string or bytes-like object'})
                elif not re.match(label_value_regex, v):
                    errors.append({str(v): f"Label value '{v}' does not match the regex {label_value_regex}"})
        elif isinstance(value, (str, bytes)):
            if not re.match(label_value_regex, value):
                errors.append({value: f"Label value '{value}' does not match the regex {label_value_regex}"})
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)
