def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not fixity or not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a non-empty dictionary")

    referenced_files = set(fixity.get('files', {}).keys())

    if referencing_files := referenced_files.intersection(manifest_files):
        raise ValueError(f"Referencing files not found in manifest: {', '.join(referencing_files)}")

    if unknown_files := manifest_files - referenced_files:
        raise ValueError(f"Unknown files in manifest: {', '.join(unknown_files)}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity block must contain 'files' key")

    if not isinstance(fixity['files'], list):
        raise ValueError("'files' key must be a list")

    allowed_files = set(manifest_files)

    for file_info in fixity['files']:
        if not isinstance(file_info, dict):
            raise ValueError("Each file in 'files' list must be a dictionary")

        if 'name' not in file_info:
            raise ValueError("Each file dictionary must contain 'name' key")

        if 'hash' not in file_info:
            raise ValueError("Each file dictionary must contain 'hash' key")

        if file_info['name'] not in allowed_files:
            raise ValueError(f"File '{file_info['name']}' not found in manifest")

        allowed_files.remove(file_info['name'])

    if allowed_files:
        raise ValueError(f"Files listed in manifest but not in fixity block: {allowed_files}")

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """

    # Check if the fixity block is a dictionary
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")

    # Ensure the required keys exist
    required_keys = {'algo', 'value'}
    missing_keys = required_keys - set(fixity.keys())
    if missing_keys:
        raise ValueError(f"Missing required keys: {missing_keys}")

    # Validate the fixity block for each file
    for file_path, fixity_info in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f"File {file_path} not found in manifest")

        if not all(key in fixity_info for key in required_keys):
            raise ValueError(f"Invalid fixity information for file {file_path}")

        if fixity_info['algo'] not in ('md5', 'sha1', 'sha256'):
            raise ValueError(f"Unsupported fixity algorithm for file {file_path}: {fixity_info['algo']}")

        if not isinstance(fixity_info['value'], str):
            raise ValueError(f"Fixity value for file {file_path} must be a string")

    return True

