def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    new_args = []
    for expr in args:
        if isinstance(expr, tuple) and len(expr) == 2:
            op, sub_expr = expr
            if op == '&':
                if isinstance(sub_expr[0], tuple) and sub_expr[0][0] == '|':
                    new_args.append(sub_expr[0][1])  # A | (A & B) = A
                elif isinstance(sub_expr[1], tuple) and sub_expr[1][0] == '&':
                    new_args.append(sub_expr[0])  # A & (A | B) = A
                elif isinstance(sub_expr[1], tuple) and sub_expr[1][0] == '&':
                    new_args.append((op, (sub_expr[0], sub_expr[1][1])))  # A & (~A | B) = A & B
            elif op == '|':
                if isinstance(sub_expr[0], tuple) and sub_expr[0][0] == '&':
                    new_args.append(sub_expr[0][1])  # A & (A | B) = A
                elif isinstance(sub_expr[1], tuple) and sub_expr[1][0] == '&':
                    new_args.append(sub_expr[0])  # A | (A & B) = A
                elif isinstance(sub_expr[1], tuple) and sub_expr[1][0] == '&':
                    new_args.append((op, (sub_expr[0], sub_expr[1][1])))  # A | (~A & B) = A | B
        else:
            new_args.append(expr)
    return new_args

def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """

    def apply_absorption expr1, expr2):
        if expr1 == expr2 or expr1 == 'True':
            return expr1
        elif expr2 == 'True':
            return expr1
        else:
            return expr1 + ' | ' + expr2

    def apply_negative_absorption(expr1, expr2):
        if expr1 == 'False':
            return expr2
        elif expr2 == 'False':
            return expr1
        else:
            return expr1 + ' & ' + expr2

    result = []
    for expr in args:
        if expr.startswith('A & (A |'):
            result.append(apply_absorption(expr, expr[3:]))
        elif expr.startswith('A | (A &'):
            result.append(apply_absorption(expr, expr[3:]))
        elif expr.startswith('A & (~A |'):
            result.append(apply_negative_absorption(expr, expr[3:]))
        elif expr.startswith('A | (~A &'):
            result.append(apply_negative_absorption(expr, expr[3:]))
        else:
            result.append(expr)

    return result

