def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def simplify(expr):
        if isinstance(expr, tuple):
            op, a, b = expr
            if op == 'and':
                if a == b:
                    return a
                elif a == 'not' and b[1] == a[1]:
                    return a[1]
            elif op == 'or':
                if a == b:
                    return a
                elif a == 'not' and b[1] == a[1]:
                    return a[1]
        return expr

    def negative_absorb(expr):
        if isinstance(expr, tuple):
            op, a, b = expr
            if op == 'and':
                if a == 'not' and b[1] == a[1]:
                    return b[1]
            elif op == 'or':
                if a == 'not' and b[1] == a[1]:
                    return b[1]
        return expr

    return [simplify(negative_absorb(expr)) for expr in args]

