def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    result = []
    for arg in args:
        if ' & ' in arg:
            parts = arg.split(' & ')
            if parts[0] in parts[1]:
                result.append(parts[0])
            else:
                result.append(arg)
        elif ' | ' in arg:
            parts = arg.split(' | ')
            if parts[0] in parts[1]:
                result.append(parts[0])
            else:
                result.append(arg)
        elif ' & (~' in arg:
            parts = arg.split(' & (~')
            if parts[0] in parts[1]:
                result.append(arg.replace('& (~', '& '))
            else:
                result.append(arg)
        elif ' | (~' in arg:
            parts = arg.split(' | (~')
            if parts[0] in parts[1]:
                result.append(arg.replace('| (~', '| '))
            else:
                result.append(arg)
        else:
            result.append(arg)
    return result
