def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for obj in self.root_hierarchy:
        num_objects += 1
        if validate_objects:
            try:
                self._validate_object(obj)
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    print(f"Warning: {e}")
        if check_digests:
            if self._check_digest(obj):
                good_objects += 1
            else:
                if show_warnings:
                    print("Warning: Digest check failed for object")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    for obj in self._objects:
        num_objects += 1
        if validate_objects:
            try:
                obj.validate()
                good_objects += 1
            except Exception as e:
                if show_warnings:
                    import warnings
                    warnings.warn(f"Validation failed for object: {obj.id}. Error: {e}")
        if check_digests:
            try:
                obj.check_digest()
            except Exception as e:
                if show_warnings:
                    import warnings
                    warnings.warn(f"Digest check failed for object: {obj.id}. Error: {e}")

    return num_objects, good_objects

