def next_version(version):
    """
    Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if version:
        version_parts = version.split('.')
        if version_parts:
            last_part = int(version_parts[-1])
            version_parts[-1] = str(last_part + 1)
            return '.'.join(version_parts)
    return version

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    version_parts = list(map(int, version.split('.')))
    if not version_parts:
        return '0.0.1'

    # Start from the rightmost part
    for i in range(len(version_parts) - 1, -1, -1):
        if version_parts[i] < 9:
            version_parts[i] += 1
            return '.'.join(map(str, version_parts))
        version_parts[i] = 0

    # If all parts were 9s, append a new part
    version_parts.append(1)
    return '.'.join(map(str, version_parts))

