def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    root_inventory = {}
    different_digests = {}

    for version_dir in version_dirs:
        # Load inventory for the current version
        current_inventory = load_inventory(version_dir)
        if not current_inventory:
            raise ValueError(f"No inventory found for version {version_dir}")

        # Check if the inventory exists up to the current version
        if current_inventory != root_inventory:
            if not root_inventory:
                root_inventory = current_inventory
            else:
                raise ValueError(f"Inventory for version {version_dir} differs from previous versions")

        # Check content digests
        current_digests = current_inventory.get('digests', {})
        for digest_key, digest_value in current_digests.items():
            if digest_key not in root_inventory.get('digests', {}):
                different_digests[digest_key] = digest_value

    return different_digests
