def parse_arguments(*unparsed_arguments):
    '''
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    '''
    from argparse import ArgumentParser, Namespace, _SubParsersAction, _ActionsContainer

    # Define the main parser and add subparsers
    parser = ArgumentParser(add_help=False)
    subparsers = parser.add_subparsers(dest='subparser_name')

    # Function to handle parsing based on the subparser
    def parse_subparser(subparser, unparsed_args):
        if isinstance(subparser.popitem()[1], _SubParsersAction):
            return {subparser_name: parse_subparser(subparser[subparser_name], unparsed_args)}
        else:
            return vars(subparser.parse_args(unparsed_args))

    # Parse arguments and determine the subparser used
    namespace = parser.parse_args(unparsed_arguments)
    if namespace.subparser_name is None:
        return {'global': parse_subparser({**parser._actions[0].choices, '': parser}, unparsed_arguments)}
    else:
        return {namespace.subparser_name: parse_subparser({namespace.subparser_name: subparsers[namespace.subparser_name]}, unparsed_arguments[1:])]

