def _merge_mapping_nodes(lhs_node, rhs_node):
    combined_map = dict(lhs_node.value + rhs_node.value)
    for key, value in combined_map.items():
        if isinstance(value, ruamel.yaml.nodes.MappingNode):
            left_value = next(
                item.value for item in lhs_node.value if item[0].value == key.value
            )
            right_value = next(
                item.value for item in rhs_node.value if item[0].value == key.value
            )
            combined_map[key] = _merge_mapping_nodes(left_value, right_value)
    return ruamel.yaml.nodes.MappingNode(tag='tag:yaml.org,2002:map', value=list(combined_map.items()))
