def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    import argparse
    import sys

    borgmatic_parser = argparse.ArgumentParser(description='borgmatic: backup, prune, & restore with Borg')
    subparsers = borgmatic_parser.add_subparsers(dest='subcommand')

    # Add subparsers for borgmatic commands
    import borgmatic
    borgmatic.config.check_config()
    borgmatic.create_parser(subparsers)
    borgmatic.service_parser = borgmatic.service.create_parser(subparsers)

    def _generate_bash_completion(main_parser, subcommand_name=None):
        completion_script = []
        main_command completing ${main_parser.prog}\n"
        completion_script.append('    completing ${main_parser.prog}\n')
        if subcommand_name:
            subcommand = main_parser.find_subcommand(subcommand_name)
            if not subcommand:
                return completion_script
        else:
            subcommand = main_parser

        types = ["option", "argument"]
        all_params = sorted(
            subcommand.get_params(), key=lambda p: types.index(p.param_type_name)
        )

        def get_name(param):
            return max(param.opts, key=len)

        for param in all_params:
            if param.param_type_name == "option":
                completion_script.append(f'        option="{get_name(param)}"')
            elif param.param_type_name == "argument":
                completion_script.append(f'        option=":{get_name(param)}"')

        return completion_script

    completion_script = _generate_bash_completion(borgmatic_parser)
    return '\n'.join(completion_script)

