            if isinstance(feature, tuple):
                parsed_features.update(FeatureParser._parse_tuple(feature, new_names))
            elif isinstance(feature, dict):
                parsed_features.update(FeatureParser._parse_dict(feature, new_names))
            else:
                feature_type = FeatureType(feature)
                parsed_features[feature_type] = feature
        return parsed_features

    @staticmethod
    def _parse_tuple(features, new_names):
        """Helping function of `_parse_features` that parses a tuple."""
        name_idx = 1
        try:
            feature_type = FeatureType(features[0])
        except ValueError:
            feature_type = None
            name_idx = 0

        if feature_type and not feature_type.has_dict():
            return OrderedDict([(feature_type, ...)])
        return OrderedDict([(feature_type, FeatureParser._parse_names_tuple(features[name_idx:], new_names))])

    @staticmethod
    def _parse_dict(feature, new_names):
        """Helping function of `_parse_features` that parses a dictionary."""
        return feature

def make_parsers():
    '''
    Build a top-level parser and its subparsers and return them as a tuple.
    '''

    parser = argparse.ArgumentParser(description='Feature Parser CLI')
    sp = parser.add_subparsers(dest='command')

    parser_parse = sp.add_parser('parse', help='Parse features')
    parser_parse.add_argument('features', nargs='+', help='Feature definitions')

    return parser, sp
