def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        seen.add(c)

        for sub_c in c.__subclasses__():
            if sub_c not in seen:
                queue.append(sub_c)

    return seen
