        if status != 0:
            error_kwargs['output'] = output.decode('utf-8')
            error_kwargs['directory'] = cwd
            raise Exception(error_message, **error_kwargs)
        return output.decode('utf-8')

    ignored_files = git("ls-files --ignored", "Failed to find ignored files")

