from typing import Optional, Set

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for s, p, o in graph.triples((None, prop, None)):
        roots.discard(o)
        roots.add(s)

    new_roots = set(roots)
    while new_roots:
        old_roots = new_roots.copy()
        for s, p, o in graph.triples((None, prop, None)):
            if s in old_roots:
                new_roots.discard(o)
                new_roots.add(s)
        if old_roots == new_roots:
            break

    return roots
