from rdflib import Graph, URIRef
from typing import Optional, Set

def find_roots(
    graph: Graph, prop: URIRef, roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    nodes = set(graph.subjects())
    processed = set()

    while nodes:
        node = nodes.pop()
        if node in processed:
            continue
        parents = set(graph.objects(None, prop))
        if any(parent in roots for parent in parents):
            roots.add(node)
        else:
            processed.add(node)
            nodes.update(graph.predecessors(node))

    return roots
