from rdflib import Graph, URIRef, Node

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    if roots is None:
        roots = set()

    for subject, predicate, object in graph:
        if predicate == prop:
            roots.discard(object)

    for subject, predicate, object in graph:
        if predicate == prop and object not in roots:
            roots.add(subject)

    return roots
