def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """

    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            with open(filename, 'r') as fd:
                raw_config = fd.read()
                if 'toml' in filename:
                    config = toml.loads(raw_config)
                elif 'yaml' in filename:
                    config = yaml.safe_load(raw_config)
                else:
                    raise ValueError(f"Unsupported file format: {filename}")

                if overrides:
                    config.update(overrides)

                if resolve_env:
                    config = resolve_environment_variables(config)

                config_dict[filename] = config
        except FileNotFoundError:
            logging.error(f"Configuration file not found: {filename}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f"Configuration file not found: {filename}", [], None))
        except toml.decoder.TomlDecodeError as e:
            logging.error(f"Failed to parse TOML file {filename}: {e}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f"Failed to parse TOML file {filename}: {e}", [], None))
        except yaml.YAMLError as e:
            logging.error(f"Failed to parse YAML file {filename}: {e}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f"Failed to parse YAML file {filename}: {e}", [], None))
        except Exception as e:
            logging.error(f"An unexpected error occurred while loading {filename}: {e}")
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f"An unexpected error occurred while loading {filename}: {e}", [], None))

    return config_dict, log_records

def resolve_environment_variables(config):
    """
    Recursively resolve environment variables in the configuration dictionary.
    """
    if isinstance(config, dict):
        for key, value in config.items():
            config[key] = resolve_environment_variables(value)
    elif isinstance(config, list):
        for i, item in enumerate(config):
            config[i] = resolve_environment_variables(item)
    elif isinstance(config, str) and config.startswith('${'):
        import os
        clean_key = config[2:-1]
        env_value = os.getenv(clean_key)
        return env_value if env_value else config
    return config

