def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    if make_value is None:
        make_value = lambda bin_: bin_

    if get_coordinate not in ["left", "right", "middle"]:
        raise ValueError("get_coordinate must be 'left', 'right', or 'middle'")

    if scale is not True and scale is not None:
        raise ValueError("scale must be None or True")

    if len(field_names) != (1 if make_value is not None else 0):
        raise ValueError("The number of field_names must be the same as the dimension of the result")

    points = []
    for bin_, value in zip(hist.bins, hist.values):
        if get_coordinate == "left":
            x = bin_.left
        elif get_coordinate == "right":
            x = bin_.right
        elif get_coordinate == "middle":
            x = bin_.mid

        if make_value is not None:
            y = make_value(value)
        else:
            y = value

        points.append((x, y))

    graph = Graph(field_names)
    graph.add_points(points)

    if scale is True:
        graph.set_scale(hist.scale)

    return graph
