def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    # Check for explicit metaclass hint in bases
    for base in bases:
        if explicit_mc is None:
            explicit_mc = getattr(base, '__metaclass__', None)

    # Use the first base's metaclass if no explicit one is found
    if explicit_mc is None:
        for base in bases:
            explicit_mc = getattr(base, '__metaclass__', None)
            if explicit_mc:
                break

    # If still no metaclass found, default to type
    if explicit_mc is None:
        explicit_mc = type

    return explicit_mc
