def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def add_attributes(url):
        return 'target="_blank" rel="noopener noreferrer"'

    def linkify(m):
        url = m.group(0)
        if not url.startswith('http'):
            url = 'http://' + url
        return f'<a {add_attributes(url)} href="{url}">{url}</a>'

    import re
    return re.sub(r'\bhttps?://\S+', linkify, text)

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""

    def linkify_url(url):
        return f'<a href="{url}" target="_blank" rel="noopener noreferrer">{url}</a>'

    def linkify_text_link(text):
        # Simple heuristic to detect URLs in plain text
        import re
        return re.sub(r'http[s]?://(?:[a-zA-Z]|[0-9]|[$-_@.&+]|[!*\\(\\),]|(?:%[0-9a-fA-F][0-9a-fA-F]))+', linkify_url, text)

    # Process links in the text
    processed_text = linkify_text_link(text)

    return processed_text

