def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    from xml.etree import ElementTree as ET

    try:
        parsed = json.loads(document)
        if "links" in parsed:
            links = parsed["links"]
            return {
                "hcard_url": next((link["href"] for link in links if link["rel"] == "http://microformats.org/profile/hcard"), None),
                "public_key": next((link["href"] for link in links if link["rel"] == "http://schemas.diaspora*org/posts/public_key"), None)
            }
    except json.JSONDecodeError:
        pass

    try:
        parsed = ET.fromstring(document)
        hcard_url = parsed.find('{http://www.w3.org/2005/Atom}link[@rel="http://microformats.org/profile/hcard"]')
        public_key = parsed.find('{http://www.w3.org/2005/Atom}link[@rel="http://schemas.diaspora*org/posts/public_key"]')
        return {
            "hcard_url": hcard_url.attrib["href"] if hcard_url is not None else None,
            "public_key": public_key.attrib["href"] if public_key is not None else None
        }
    except ET.ParseError:
        pass

    return {}
