def list_of_file_names(settings_dirs, spec_option):
    """Return a list of file names based on the given settings directories and specification option."""
    if isinstance(settings_dirs, (list, tuple)):
        files = []
        for directory in settings_dirs:
            if os.path.isdir(directory):
                for root, _, filenames in os.walk(directory):
                    for filename in filenames:
                        if filename.endswith(spec_option):
                            files.append(os.path.join(root, filename))
        return sorted(files)
    else:
        raise ValueError("settings_dirs must be a list or tuple of directories")
