def validate_from_content(cls, spec_content=None):
    """validates that spec (YAML) content has all required fields

    :param spec_content: content of spec file
    :raise IRValidatorException: when mandatory data
    is missing in spec file
    :return: Dictionary with data loaded from a spec (YAML) file
    """

    if spec_content is None:
        raise IRValidatorException("spec_content argument must be supplied")

    try:
        spec_data = yaml.safe_load(spec_content)
    except Exception as e:
        raise IRValidatorException(f"Error parsing spec content: {e}")

    required_fields = cls.get_required_fields()

    for field in required_fields:
        if field not in spec_data:
            raise IRValidatorException(f"Missing required field: {field}")

    return spec_data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_dirs = parser_dict.pop('include_dirs', [])
    for include_dir in include_dirs:
        include_file = os.path.join(include_dir, 'parser_dict.yaml')
        if os.path.exists(include_file):
            with open(include_file, 'r') as f:
                included_dict = yaml.safe_load(f)
                parser_dict.update(included_dict)
                self._include_groups(included_dict)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    for key, value in parser_dict.items():
        if key == 'include':
            file_path = value
            with open(file_path, 'r') as file:
                include_dict = json.load(file)
            parser_dict.update(include_dict)
        elif isinstance(value, dict):
            self._include_groups(value)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_directives = []
    for key, value in parser_dict.items():
        if isinstance(value, dict) and 'include' in value:
            include_directives.append((key, value['include']))
    for key, include_path in include_directives:
        include_file = open(include_path, 'r')
        include_content = include_file.read()
        include_file.close()
        include_dict = eval(include_content)
        parser_dict[key] = include_dict
    return parser_dict

def _include_groups(self, parser_dict):
