def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec: the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when`` condition
    """
    matched_args = []
    for option in options_spec:
        if 'required_when' in option:
            if self._evaluate_required_when(command_name, option, args):
                matched_args.append(option['name'])
    return matched_args

def _evaluate_required_when(self, command_name, option, args):
    """Evaluates the ``required_when`` condition for a given option.

    :param command_name: the command name.
    :param option: the command spec option.
    :param args: the received input arguments
    :return: bool, True if the condition is matched, False otherwise
    """
    when = option['required_when']
    if isinstance(when, str):
        return args.get(when, None) is not None
    elif isinstance(when, list):
        return all(args.get(arg, None) is not None for arg in when)
    elif isinstance(when, dict):
        for key, value in when.items():
            if isinstance(value, list):
                if args.get(key, None) not in value:
                    return False
            else:
                if args.get(key, None) != value:
                    return False
        return True
    else:
        raise ValueError("Invalid ``required_when`` condition type")
