def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        try:
            # Check if the key corresponds to an integer argument
            if parser_name in ['main', 'virsh'] and key in ['port', 'pid', 'id']:
                values_dict[key] = int(value)
            # Check if the key corresponds to a boolean argument
            elif parser_name == 'main' and key in ['debug', 'verbose']:
                values_dict[key] = value.lower() in ['true', '1', 't', 'y', 'yes']
            # Check if the key corresponds to a list argument
            elif parser_name == 'main' and key == 'tags':
                values_dict[key] = value.split(',')
        except (ValueError, AttributeError):
            # If conversion fails, keep the original value
            continue

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    conversion_dict = {
        'main': {'port': int},
        'virsh': {'domain': str, 'state': bool},
        'ospd': {'threshold': float}
    }

    for key, value in conversion_dict.get(parser_name, {}).items():
        if key in values_dict:
            values_dict[key] = value(values_dict[key])

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    plugin_spec_path = os.path.join(plugin_dir, 'spec.json')
    with open(plugin_spec_path, 'r') as f:
        spec = json.load(f)

    flat_dict = {}
    def flatten(x, name=''):
        if type(x) is dict:
            for a in x:
                flatten(x[a], name + a + '_')
        elif type(x) is list:
            i = 0
            for a in x:
                flatten(a, name + str(i) + '_')
                i += 1
        else:
            flat_dict[name[:-1]] = x

    flatten(spec)
    return flat_dict

